// ===== IMPOSTAZIONI — modifica solo i valori a destra =====
return [
  {
    json: {
      // ID del Google Sheet "NOVA - Database" (la parte dell'URL tra /d/ e /edit)
      id_foglio: 'INCOLLA_QUI_ID_GOOGLE_SHEET',
      // ID del workflow "00 - NOVA - Gmail (caselle)" (lo trovi nell'URL del workflow)
      id_workflow_gmail: 'INCOLLA_QUI_ID_WORKFLOW_00',

      // Dove e cosa cercare su Google Maps: il sistema prova le combinazioni città × categoria, una alla volta
      citta: ['Milano, Italia', 'Monza, Italia', 'Bergamo, Italia'],
      categorie: ['ristoranti', 'parrucchieri', 'centri estetici'],

      // Cerca nuovi lead solo se nella CODA ci sono meno di questi lead "NUOVO"
      soglia_coda_minima: 80,
      // Quante ricerche (città × categoria) fare al massimo ogni mattina
      ricerche_per_giorno: 2,
      // Risultati massimi per ricerca su Google Maps (più alto = più crediti Apify)
      risultati_per_ricerca: 40,
      // Dopo quanti giorni una combinazione città × categoria può essere ripetuta
      giorni_prima_di_ripetere: 90,

      // Actor Apify per Google Maps
      apify_actor: 'compass~crawler-google-places',

      // Avvisi (es. "contatti in esaurimento")
      email_avvisi: 'tua.email@esempio.it',
      slot_avvisi: 1, // da quale casella del workflow 00 partono gli avvisi
    },
  },
];

// ---- Funzioni comuni NOVA (incluse automaticamente in ogni nodo Code) ----
const CFG = $('IMPOSTAZIONI').first().json;

// Righe lette da un nodo Google Sheets (scarta le righe vuote)
function righe(nodo, colonnaChiave) {
  return $(nodo)
    .all()
    .map((i) => i.json)
    .filter((r) => r && String(r[colonnaChiave] ?? '').trim() !== '');
}

function si(v) {
  return ['si', 'sì', 'yes', 'y', 'true', '1', 'x', 'ok'].includes(String(v ?? '').trim().toLowerCase());
}

function pulisci(v) {
  return String(v ?? '').trim();
}

function normEmail(v) {
  return pulisci(v).toLowerCase();
}

function dominio(email) {
  return normEmail(email).split('@')[1] || '';
}

// Data di oggi nel fuso del workflow (YYYY-MM-DD)
function oggi() {
  return $now.toFormat('yyyy-MM-dd');
}

// Interpreta le date scritte nel foglio: 2026-10-05, 05/10/2026, numero seriale di Sheets
function leggiData(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') {
    return DateTime.fromISO('1899-12-30', { zone: $now.zoneName }).plus({ days: Math.floor(v) }).startOf('day');
  }
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return DateTime.fromObject({ year: +m[1], month: +m[2], day: +m[3] }, { zone: $now.zoneName });
  m = s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})/);
  if (m) return DateTime.fromObject({ year: +m[3], month: +m[2], day: +m[1] }, { zone: $now.zoneName });
  return null;
}

// Giorni interi trascorsi da una data del foglio (null se la data manca)
function giorniDa(v) {
  const d = leggiData(v);
  if (!d) return null;
  return Math.floor($now.startOf('day').diff(d.startOf('day'), 'days').days);
}

function scegli(lista) {
  return lista[Math.floor(Math.random() * lista.length)];
}

// Sostituisce {segnaposto} nel testo
function riempi(testo, valori) {
  return String(testo ?? '').replace(/\{([a-z_]+)\}/gi, (tutto, k) =>
    valori[k] !== undefined && valori[k] !== null ? String(valori[k]) : tutto,
  );
}

// Testi dalla scheda TESTI: { chiave: [varianti...] }
function caricaTesti(nodo) {
  const testi = {};
  for (const r of righe(nodo, 'chiave')) {
    const k = pulisci(r.chiave).toLowerCase();
    const t = String(r.testo ?? '').replace(/\\n/g, '\n').trim();
    if (!t) continue;
    (testi[k] = testi[k] || []).push(t);
  }
  return testi;
}

function testo(testi, chiave, obbligatorio = true) {
  const v = testi[chiave];
  if (!v || !v.length) {
    if (obbligatorio) {
      throw new Error(`Nella scheda TESTI manca la chiave "${chiave}". Aggiungila prima di attivare il workflow.`);
    }
    return '';
  }
  return scegli(v);
}

// Caselle collegate nel workflow 00 (scheda CASELLE)
function caselle(nodo) {
  return righe(nodo, 'email')
    .filter((c) => si(c.attiva))
    .map((c) => ({
      ...c,
      email_foglio: pulisci(c.email),
      slot: parseInt(c.slot, 10),
      email: normEmail(c.email),
      ruolo: pulisci(c.ruolo).toUpperCase() || 'INVIO',
      pronta: pulisci(c.stato_warmup).toUpperCase() === 'COMPLETATO',
    }))
    .filter((c) => c.slot >= 1 && c.slot <= 10);
}

// Elenco opt-out / bounce (scheda BLACKLIST)
function caricaBlacklist(nodo) {
  const email = new Set();
  const domini = new Set();
  for (const r of $(nodo).all().map((i) => i.json)) {
    if (pulisci(r.email)) email.add(normEmail(r.email));
    if (pulisci(r.dominio)) domini.add(pulisci(r.dominio).toLowerCase());
  }
  return { email, domini, contiene: (e) => email.has(normEmail(e)) || domini.has(dominio(e)) };
}

// ---- Logica del nodo ----
// Controlla la coda: se ci sono abbastanza lead NUOVO non fa nulla, altrimenti sceglie le prossime ricerche.
const coda = righe('Leggi CODA', 'lead_id');
const nuovi = coda.filter((r) => pulisci(r.stato).toUpperCase() === 'NUOVO').length;
if (nuovi >= CFG.soglia_coda_minima) return [];

const recenti = new Set(
  righe('Leggi RICERCHE', 'citta')
    .filter((r) => {
      const g = giorniDa(r.data);
      return g === null || g < CFG.giorni_prima_di_ripetere;
    })
    .map((r) => `${pulisci(r.citta).toLowerCase()}|${pulisci(r.categoria).toLowerCase()}`),
);

const disponibili = [];
for (const citta of CFG.citta) {
  for (const categoria of CFG.categorie) {
    if (!recenti.has(`${citta.toLowerCase()}|${categoria.toLowerCase()}`)) disponibili.push({ citta, categoria });
  }
}

const out = disponibili.slice(0, CFG.ricerche_per_giorno).map((r) => ({ json: { _dest: 'ricerca', ...r } }));

// Avviso se le combinazioni stanno finendo
const restanti = disponibili.length - out.length;
if (restanti <= CFG.ricerche_per_giorno) {
  out.push({
    json: {
      _dest: 'avviso',
      azione: 'invia',
      slot: CFG.slot_avvisi,
      a: CFG.email_avvisi,
      oggetto: 'NOVA: contatti in esaurimento',
      testo:
        `Ciao,\n\nnella CODA ci sono ${nuovi} lead da contattare e restano solo ${restanti} ricerche nuove ` +
        `(città × categoria) da fare.\n\nPer non restare senza contatti apri il workflow "01 - NOVA - Trova Nuovi Lead" ` +
        `e nel nodo IMPOSTAZIONI aggiungi nuove città o categorie, oppure aumenta "risultati_per_ricerca".\n\nNOVA`,
      rif: 'avviso_coda',
    },
  });
}
return out;

